            $short = ($tag ? ucfirst($tag)."-tag " : "") . "{$race} {$feed} " . strtolower($p) . ($dop ? " protected by the Los Pedroches PDO" : "") . ($is_sliced ? " supplied in sliced packs" : "") . ", from pigs {$descfeed}." . ($shipping ? " Shipping included." : "");
