}

$backup = [];
foreach ($items as $id => $m) {
    $id = (int)$id;
    $p = get_post($id);
    if (!$p || $p->post_type !== 'product' || $p->post_status !== 'publish') throw new Exception("Missing product $id");
    if ($p->post_title !== $m['title'] || $p->post_name !== $m['slug']) throw new Exception("Identity mismatch $id");
    $u = get_userdata((int)$p->post_author);
    if (!$u || stripos((string)$u->display_name, 'Hidalgo de la Jara') === false) throw new Exception("Vendor mismatch $id");
    if (get_post_meta($id, '_stock_status', true) !== 'instock') throw new Exception("Stock mismatch $id");
    $backup[$id] = ['post_excerpt'=>$p->post_excerpt,'post_content'=>$p->post_content,'en_excerpt'=>get_post_meta($id,'_en_US_post_excerpt',true),'en_content'=>get_post_meta($id,'_en_US_post_content',true)];
}
$key = 'mo_hidalgo_products_copy_backup_20260831';
if (get_option($key, false) === false) { add_option($key, $backup, '', 'no'); echo "BACKUP created $key\n"; } else echo "BACKUP exists $key\n";

foreach ($items as $id => $m) {
    $id = (int)$id;
    [$es_ex, $es_body] = make_copy($m, 'es', $producer_es);
    [$en_ex, $en_body] = make_copy($m, 'en', $producer_en);
    $r = wp_update_post(['ID'=>$id,'post_excerpt'=>$es_ex,'post_content'=>$es_body], true);
    if (is_wp_error($r)) throw new Exception("Update failed $id: ".$r->get_error_message());
    update_post_meta($id, '_en_US_post_excerpt', $en_ex);
    update_post_meta($id, '_en_US_post_content', $en_body);
    clean_post_cache($id);
    $p = get_post($id); $e = (string)get_post_meta($id, '_en_US_post_content', true);
    if (strpos($p->post_content, 'Sobre Hidalgo de la Jara') === false || strpos($p->post_content, 'Preguntas frecuentes') === false) throw new Exception("ES verify failed $id");
    if (strpos($e, 'About Hidalgo de la Jara') === false || strpos($e, 'Frequently asked questions') === false) throw new Exception("EN verify failed $id");
    echo "UPDATED_AND_VERIFIED ID=$id {$m['title']}\n";
}
echo "DONE hidalgo_products=" . count($items) . "\n";
